def test_pinned_uv_named_refusals_sha256_size_short_read_bad_members_and_version_mismatch(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Card Item 5: each of these refuses by name:
    - a sha256 mismatch (`PINNED_UV_SHA256_MISMATCH`), verified BEFORE unpacking (`zipfile.ZipFile` never called);
    - a wrong size (`PINNED_UV_SIZE_MISMATCH`);
    - a short read (`PINNED_UV_DOWNLOAD_FAILED`);
    - a traversal member (`../x`) and an absolute member (`/etc/passwd`) (`PINNED_UV_BAD_MEMBER`);
    - a symlink member (`PINNED_UV_BAD_MEMBER`);
    - a missing `uv` member (`PINNED_UV_BAD_MEMBER`);
    - `--version` reporting `0.13.4` (`PINNED_UV_VERSION_MISMATCH`);
    - launcher's gate refusal-class grep reports `"VM gate refused"`, not `"liveness"`.
    """
    _pin = _use_per_test_pinned_uv_dir(tmp_path, monkeypatch)
    _mock_sufficient_vm_disk(monkeypatch)
    valid_whl, valid_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "valid_whl",
        uv_binary_version="0.13.5",
    )

    # 1. `PINNED_UV_SHA256_MISMATCH` — verified BEFORE unpacking (`zipfile.ZipFile` must NOT be called)
    tampered_whl, tampered_sha, tampered_size = fake_colab.build_fixture_uv_wheel(
        tmp_path / "tampered_whl",
        tamper_after_build=True,
    )
    assert tampered_size == 17_211_825
    assert tampered_sha != valid_sha

    zipfile_opened = False
    real_zipfile = zipfile.ZipFile

    def _spy_zipfile(*a: Any, **kw: Any) -> Any:
        nonlocal zipfile_opened
        zipfile_opened = True
        return real_zipfile(*a, **kw)

    monkeypatch.setattr(zipfile, "ZipFile", _spy_zipfile)
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(tampered_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_sha:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_sha_mismatch",
            expected_sha256=valid_sha,
        )
    assert exc_sha.value.failure_class == "PINNED_UV_SHA256_MISMATCH"
    assert not zipfile_opened
    monkeypatch.setattr(zipfile, "ZipFile", real_zipfile)

    # 2. `PINNED_UV_SIZE_MISMATCH` — wrong size (e.g. 17,211,000 bytes and > 18,000,000 cap)
    wrong_size_whl, wrong_size_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "wrong_size_whl",
        target_size=17_211_000,
    )
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(wrong_size_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_size:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_size_mismatch",
            expected_sha256=wrong_size_sha,
        )
    assert exc_size.value.failure_class == "PINNED_UV_SIZE_MISMATCH"

    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(b"X" * 18_000_001),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_cap:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_cap_mismatch",
            expected_sha256=valid_sha,
        )
    assert exc_cap.value.failure_class == "PINNED_UV_SIZE_MISMATCH"

    # 3. `PINNED_UV_DOWNLOAD_FAILED` — short read (Content-Length 17,211,825 but stream ends at 500,000 bytes)
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(
            valid_whl.read_bytes()[:500_000],
            content_length=17_211_825,
        ),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_short:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_short_read",
            expected_sha256=valid_sha,
        )
    assert exc_short.value.failure_class == "PINNED_UV_DOWNLOAD_FAILED"
    assert "Short read" in exc_short.value.detail

    # 4. `PINNED_UV_BAD_MEMBER` — traversal member (`../x`) and absolute member (`/etc/passwd`)
    trav_whl, trav_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "trav_whl",
        extra_member_name="../x",
    )
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(trav_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_trav:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_trav",
            expected_sha256=trav_sha,
        )
    assert exc_trav.value.failure_class == "PINNED_UV_BAD_MEMBER"
    assert "../x" in exc_trav.value.detail

    abs_whl, abs_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "abs_whl",
        extra_member_name="/etc/passwd",
    )
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(abs_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_abs:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_abs",
            expected_sha256=abs_sha,
        )
    assert exc_abs.value.failure_class == "PINNED_UV_BAD_MEMBER"
    assert "/etc/passwd" in exc_abs.value.detail

    # 5. `PINNED_UV_BAD_MEMBER` — symlink member (mode `0o120777` in zip external_attr)
    sym_whl, sym_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "sym_whl",
        extra_member_name="uv-0.13.5.data/scripts/uv_symlink",
        extra_member_is_symlink=True,
    )
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(sym_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_sym:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_sym",
            expected_sha256=sym_sha,
        )
    assert exc_sym.value.failure_class == "PINNED_UV_BAD_MEMBER"
    assert "symlink" in exc_sym.value.detail

    # 6. `PINNED_UV_BAD_MEMBER` — missing `uv` member (`uv-0.13.5.data/scripts/uv` absent)
    missing_uv_whl, missing_uv_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "missing_uv_whl",
        omit_uv_member=True,
    )
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(missing_uv_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_missing:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_missing",
            expected_sha256=missing_uv_sha,
        )
    assert exc_missing.value.failure_class == "PINNED_UV_BAD_MEMBER"
    assert "uv-0.13.5.data/scripts/uv" in exc_missing.value.detail

    # 7. `PINNED_UV_VERSION_MISMATCH` — unpacked binary reports `uv 0.13.4`
    bad_ver_whl, bad_ver_sha, _ = fake_colab.build_fixture_uv_wheel(
        tmp_path / "bad_ver_whl",
        uv_binary_version="0.13.4",
    )
    monkeypatch.setattr(
        vm_judges,
        "open_pinned_uv_wheel_stream",
        lambda url, **_kw: vm_judges._FakeWheelStream(bad_ver_whl.read_bytes()),
    )
    with pytest.raises(vm_judges.RefusalError) as exc_ver:
        vm_judges.install_pinned_uv_wheel(
            pinned_uv_dir=tmp_path / "uv_bad_ver",
            expected_sha256=bad_ver_sha,
        )
    assert exc_ver.value.failure_class == "PINNED_UV_VERSION_MISMATCH"
    assert "0.13.4" in exc_ver.value.detail

    # 8. Launcher gate refusal-class grep reports "VM gate refused" (exit 2), not "liveness"
    monkeypatch.undo()
    env_gate_ref = fake_colab.setup_fake_colab_environment(
        tmp_path / "env_gate_ref",
        uv_version="uv 0.13.4",
    )
    fake_colab.set_fake_uv_python_315_state(
        env_gate_ref,
        found=True,
        uv_version="uv 0.13.4",
        uv_wheel_path=valid_whl,
        expected_uv_wheel_sha256=valid_sha,
        pinned_uv_binary_version="uv 0.13.4",
    )
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "gate_ref_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "gate_ref_data", count=4)
    out_gate_ref = tmp_path / "out_gate_ref"
    exports_ref = _base_launcher_exports(
        env_gate_ref,
        open_lock=tmp_path / "gate_ref.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_ref = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_ref} bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_gate_ref)}' --run-id gate-ref-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_ref.returncode == 2
    outcome_ref = json.loads(
        (out_gate_ref / "outcome.draft.json").read_text(encoding="utf-8")
    )
    assert "VM gate refused" in outcome_ref["why"]
    assert "PINNED_UV_VERSION_MISMATCH" in outcome_ref["why"]
    assert "liveness" not in outcome_ref["why"]


def test_force_pinned_uv_knob_forces_pinned_in_stub_and_refuses_time_one_before_colab_new(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Card Item 5 & Item 6:
    - `RDLAB_FORCE_PINNED_UV=1` with `--stub` forces the pinned wheel path even when image uv is `0.13.5`;
    - `RDLAB_FORCE_PINNED_UV=1` with `--time-one` is refused with `FORCE_PINNED_UV_INVALID` before `colab new`;
    - `RDLAB_FORCE_PINNED_UV=1 scripts/colab/launch_judges.sh --stub --until venv_sync --dry` shows the forwarded `--env`.
    """
    _pin = _use_per_test_pinned_uv_dir(tmp_path, monkeypatch)
    # 1. With `--time-one`, `RDLAB_FORCE_PINNED_UV=1` is refused before `colab new`
    env_t1 = fake_colab.setup_fake_colab_environment(tmp_path / "env_force_t1")
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "force_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "force_data", count=4)
    out_t1 = tmp_path / "out_force_t1"
    exports_t1 = _base_launcher_exports(
        env_t1,
        open_lock=tmp_path / "force_t1.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_t1 = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_t1} RDLAB_FORCE_PINNED_UV=1 bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --time-one --out-dir '{_to_wsl_path(out_t1)}' --run-id force-t1-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    assert proc_t1.returncode == 2
    assert "FORCE_PINNED_UV_INVALID" in proc_t1.stderr
    assert not env_t1["calls_log"].exists()
    assert not env_t1["sentinel_called"].exists()

    # 2. Item 6 dry listing: `RDLAB_FORCE_PINNED_UV=1 scripts/colab/launch_judges.sh --stub --until venv_sync --dry`
    hermetic_path = _hermetic_path_for(env_t1)
    proc_dry = subprocess.run(
        [
            "bash",
            "-c",
            f"export PATH='{hermetic_path}'; RDLAB_FORCE_PINNED_UV=1 bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --dry",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    assert proc_dry.returncode == 0, f"stderr={proc_dry.stderr}"
    assert "--env RDLAB_FORCE_PINNED_UV=1" in proc_dry.stdout
    assert not env_t1["calls_log"].exists()
    assert not env_t1["sentinel_called"].exists()

    # 3. With `--stub` (and image uv at `0.13.5`), `RDLAB_FORCE_PINNED_UV=1` forces the pinned wheel path
    env_stub = fake_colab.setup_fake_colab_environment(
        tmp_path / "env_force_stub",
        uv_version="uv 0.13.5",
    )
    out_stub = tmp_path / "out_force_stub"
    exports_stub = _base_launcher_exports(
        env_stub,
        open_lock=tmp_path / "force_stub.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_stub = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_stub} RDLAB_FORCE_PINNED_UV=1 bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_stub)}' --run-id force-stub-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_stub.returncode == 0, f"stderr={proc_stub.stderr}"
    vm_fs = env_stub["state_dir"] / "vm_fs"
    gate_doc = json.loads((vm_fs / "gate_status.json").read_text(encoding="utf-8"))
    status_doc = json.loads((out_stub / "status.json").read_text(encoding="utf-8"))
    receipt_doc = json.loads((out_stub / "vm_receipt.json").read_text(encoding="utf-8"))
    for doc in (gate_doc, status_doc, receipt_doc):
        assert doc["uv_source"] == "pinned-wheel"
        assert doc["uv_path"] == str(_pin / "uv")
        assert doc["uv_version"] == "uv 0.13.5"


def test_request_timeout_default_60_and_preset_value_respected_across_all_colab_calls(
    tmp_path: Path,
) -> None:
    """Card Item 4 & Item 5: `REQUEST_TIMEOUT` defaults to `60` in `scripts/colab/launch_judges.sh`,
    respects a preset value, and every `colab` call in a fake run sees it.
    """
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "req_to_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "req_to_data", count=4)

    # 1. Default `REQUEST_TIMEOUT=60` when unset
    env_def = fake_colab.setup_fake_colab_environment(tmp_path / "env_req_def")
    out_def = tmp_path / "out_req_def"
    exports_def = _base_launcher_exports(
        env_def,
        open_lock=tmp_path / "req_def.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_def = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_def} unset REQUEST_TIMEOUT; bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_def)}' --run-id req-def-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_def.returncode == 0, f"stderr={proc_def.stderr}"
    calls_def = [
        json.loads(ln)
        for ln in env_def["calls_log"].read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    assert len(calls_def) >= 6
    assert all(c["request_timeout"] == "60" for c in calls_def)

    # 2. Preset `REQUEST_TIMEOUT=120` is respected across all `colab` calls
    env_pre = fake_colab.setup_fake_colab_environment(tmp_path / "env_req_pre")
    out_pre = tmp_path / "out_req_pre"
    exports_pre = _base_launcher_exports(
        env_pre,
        open_lock=tmp_path / "req_pre.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_pre = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_pre} REQUEST_TIMEOUT=120 bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_pre)}' --run-id req-pre-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_pre.returncode == 0, f"stderr={proc_pre.stderr}"
    calls_pre = [
        json.loads(ln)
        for ln in env_pre["calls_log"].read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    assert len(calls_pre) >= 6
    assert all(c["request_timeout"] == "120" for c in calls_pre)


def test_non_stub_child_argv_uses_cuda_0_and_runner_normalizes_cuda_for_d3_transport(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Card Part 1 Item 1 & Item 4(1):
    - the non-stub child argv in `vm_judges.py` has `--device cuda:0`,
    - `bakeoff_judge` normalises `--device cuda` to `cuda:0` so `D3MiniTransport` passes `device="cuda:0"`
      to `AutoModel.from_pretrained` (assert the recorded kwarg on the fake),
    - progress lines and `judge_done/<judge>.json` record the normalised device string.
    """
    import types as _types
    from reasoning_dataset_lab.pilot_b import bakeoff_judge as bj_mod

    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "dev_norm_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "dev_norm_data", count=2)
    _attach_part_files(items_file, part_id="part-synthetic")
    run_dir = tmp_path / "run_non_stub"
    work_dir = tmp_path / "work_non_stub"
    vm_judges._ensure_dryrun_venv_python_wrapper(work_dir / "venv-judge" / "bin" / "python")
    vm_judges._ensure_dryrun_venv_python_wrapper(work_dir / "venv-d3" / "bin" / "python")

    state_dir_t1 = Path(os.environ["FAKE_COLAB_STATE_DIR"])
    subproc_log_t1 = state_dir_t1 / "judge_subprocesses.jsonl"
    if subproc_log_t1.exists():
        subproc_log_t1.unlink()

    # 1. Running `run_judges_pipeline` in `time-one` normalises child argv to `--device cuda:0`
    #    (using the fake dryrun venv python wrapper so no real GPU is touched)
    vm_judges.run_judges_pipeline(
        mode="time-one",
        part_dir=items_file.parent,
        run_dir=run_dir,
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        dryrun=False,
        repo_root=REPO_ROOT,
        work_dir=work_dir,
        progress_path=run_dir / "progress.jsonl",
        only_judge_ids=("d3-mini",),
    )

    subproc_rows = [
        json.loads(ln)
        for ln in subproc_log_t1.read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    assert len(subproc_rows) == 1
    argv_d3 = subproc_rows[0]["argv"]
    dev_idx = argv_d3.index("--device")
    assert argv_d3[dev_idx + 1] == "cuda:0"
    assert subproc_rows[0]["device"] == "cuda:0"

    # 2. `resolve_judge_device` for non-stub (`time-one`, `dryrun=False`, `real_load_on_cpu=False`) returns `"cuda:0"`
    assert (
        vm_judges.resolve_judge_device(
            mode="time-one", dryrun=False, real_load_on_cpu=False
        )
        == "cuda:0"
    )

    done_d3 = json.loads(
        (run_dir / "judge_done" / "d3-mini.json").read_text(encoding="utf-8")
    )
    assert done_d3["device"] == "cuda:0"

    # 3. `bakeoff_judge` normalises `--device cuda` to `"cuda:0"` so `D3MiniTransport` passes `device="cuda:0"`
    #    to `AutoModel.from_pretrained`
    monkeypatch.delenv("FAKE_COLAB_STATE_DIR", raising=False)
    for name in bj_mod.OFFLINE_ENV_VARS:
        monkeypatch.setenv(name, "1")

    recorded_from_pretrained: list[tuple[tuple[Any, ...], dict[str, Any]]] = []

    class _FakeD3Model:
        def system_one(self, **kwargs: Any) -> dict[str, Any]:
            q = kwargs["questions"]["supported"]
            if q["type"] == "noul":
                ans: dict[str, Any] = {"type": "noul", "noul": 0.9}
            else:
                ans = {
                    "type": "choice",
                    "choice": "supported",
                    "probabilities": {
                        "supported": 0.8,
                        "unsupported": 0.1,
                        "cannot_tell": 0.1,
                    },
                    "confidence": 0.8,
                }
            return {
                "model": "d3-mini",
                "answers": {"supported": ans},
                "usage": {"input_tokens": 32, "output_tokens": 0},
            }

    class _FakeAutoModel:
        @classmethod
        def from_pretrained(cls, *args: Any, **kwargs: Any) -> Any:
            recorded_from_pretrained.append((args, dict(kwargs)))
            return _FakeD3Model()

    class _FakeInferenceMode:
        def __enter__(self) -> None:
            return None

        def __exit__(self, *_a: Any) -> None:
            return None

    fake_tf = _types.ModuleType("transformers")
    fake_tf.__version__ = bj_mod.D3_MINI_TRANSFORMERS_VERSION  # type: ignore[attr-defined]
    fake_tf.AutoModel = _FakeAutoModel  # type: ignore[attr-defined]

    fake_torch = _types.ModuleType("torch")
    fake_torch.__version__ = "2.14.1+cu132"  # type: ignore[attr-defined]
    fake_torch.manual_seed = lambda _s: None  # type: ignore[attr-defined]
    fake_torch.inference_mode = _FakeInferenceMode  # type: ignore[attr-defined]

    monkeypatch.setitem(sys.modules, "transformers", fake_tf)
    monkeypatch.setitem(sys.modules, "torch", fake_torch)

    runner_out = tmp_path / "runner_d3_out"
    runner_done = runner_out / "judge_done" / "d3-mini.json"
    runner_prog = runner_out / "progress.jsonl"
    rc_runner = bj_mod.main_judge_runner(
        [
            "--judge",
            "d3-mini",
            "--part-dir",
            str(items_file.parent),
            "--output-dir",
            str(runner_out),
            "--receipts-dir",
            str(receipts_dir),
            "--hf-home",
            str(hf_home),
            "--device",
            "cuda",
            "--allow-remote-code-reviewed",
            D3_MINI_REVIEWED_REVISION,
            "--no-canary",
            "--progress-file",
            str(runner_prog),
        ]
    )
    assert rc_runner == 0
    assert len(recorded_from_pretrained) == 1
    _, fp_kwargs = recorded_from_pretrained[0]
    assert fp_kwargs["device"] == "cuda:0"

    runner_done_doc = json.loads(runner_done.read_text(encoding="utf-8"))
    assert runner_done_doc["device"] == "cuda:0"
    runner_prog_rows = [
        json.loads(ln)
        for ln in runner_prog.read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    assert all(r.get("device") == "cuda:0" for r in runner_prog_rows)


def test_fake_d3_runtime_rejects_indexless_cuda_and_passes_with_normalized_device(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Card Part 1 Item 4(2):
    A fake d3 runtime that raises `ValueError("Expected a torch.device with a specified index or an integer, but got:cuda")`
    on any indexless CUDA device fails at `a35534dcfa15d7ddbc42cd06b5f4d60058dc350e` and passes with the fix.
    """
    import types as _types
    from reasoning_dataset_lab.pilot_b import bakeoff_judge as bj_mod

    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "d3_idx_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "d3_idx_data", count=2)
    _attach_part_files(items_file, part_id="part-synthetic")

    monkeypatch.delenv("FAKE_COLAB_STATE_DIR", raising=False)
    for name in bj_mod.OFFLINE_ENV_VARS:
        monkeypatch.setenv(name, "1")

    class _FakeTorchDevice:
        def __init__(self, spec: Any) -> None:
            if isinstance(spec, _FakeTorchDevice):
                self.type = spec.type
                self.index = spec.index
                return
            s = str(spec)
            if s == "cpu":
                self.type = "cpu"
                self.index = None
            elif s == "cuda":
                self.type = "cuda"
                self.index = None
            elif s.startswith("cuda:"):
                self.type = "cuda"
                self.index = int(s.split(":", 1)[1])
            else:
                raise RuntimeError(f"Invalid device string: {s!r}")

        def __str__(self) -> str:
            return self.type if self.index is None else f"{self.type}:{self.index}"

    def _get_device_index(
        device: Any, optional: bool = False, allow_cpu: bool = False
    ) -> int:
        dev = device if isinstance(device, _FakeTorchDevice) else _FakeTorchDevice(device)
        if dev.type != "cuda" or dev.index is None:
            raise ValueError(
                f"Expected a torch.device with a specified index or an integer, but got:{dev}"
            )
        return int(dev.index)

    class _StrictIndexD3Model:
        def system_one(self, **kwargs: Any) -> dict[str, Any]:
            q = kwargs["questions"]["supported"]
            if q["type"] == "noul":
                ans: dict[str, Any] = {"type": "noul", "noul": 0.88}
            else:
                ans = {
                    "type": "choice",
                    "choice": "supported",
                    "probabilities": {
                        "supported": 0.85,
                        "unsupported": 0.1,
                        "cannot_tell": 0.05,
                    },
                    "confidence": 0.85,
                }
            return {
                "model": "d3-mini",
                "answers": {"supported": ans},
                "usage": {"input_tokens": 28, "output_tokens": 0},
            }

    class _StrictAutoModel:
        @classmethod
        def from_pretrained(cls, *args: Any, **kwargs: Any) -> Any:
            # Mirror d3-mini modeling_d3.py:1372 -> bitsandbytes -> torch.cuda._utils._get_device_index(torch.device(device))
            _get_device_index(_FakeTorchDevice(kwargs.get("device")))
            return _StrictIndexD3Model()

    class _FakeInferenceMode:
        def __enter__(self) -> None:
            return None

        def __exit__(self, *_a: Any) -> None:
            return None

    fake_tf = _types.ModuleType("transformers")
    fake_tf.__version__ = bj_mod.D3_MINI_TRANSFORMERS_VERSION  # type: ignore[attr-defined]
    fake_tf.AutoModel = _StrictAutoModel  # type: ignore[attr-defined]

    fake_torch = _types.ModuleType("torch")
    fake_torch.__version__ = "2.14.1+cu132"  # type: ignore[attr-defined]
    fake_torch.device = _FakeTorchDevice  # type: ignore[attr-defined]
    fake_torch.manual_seed = lambda _s: None  # type: ignore[attr-defined]
    fake_torch.inference_mode = _FakeInferenceMode  # type: ignore[attr-defined]

    monkeypatch.setitem(sys.modules, "transformers", fake_tf)
    monkeypatch.setitem(sys.modules, "torch", fake_torch)

    # Confirm the fake runtime raises the exact ValueError on indexless "cuda"
    with pytest.raises(
        ValueError,
        match=r"Expected a torch\.device with a specified index or an integer, but got:cuda",
    ):
        _StrictAutoModel.from_pretrained("dummy", device="cuda")

    # Passing `device="cuda"` into `run_bakeoff_judge` normalises to `"cuda:0"` and succeeds
    summary = bj_mod.run_bakeoff_judge(
        judge="d3-mini",
        part_dir=items_file.parent,
        output_dir=tmp_path / "d3_idx_out",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        device="cuda",
        allow_remote_code_reviewed=D3_MINI_REVIEWED_REVISION,
        fake_transport=False,
        run_canary=False,
    )
    assert summary["device"] == "cuda:0"
    assert summary["calls_count"] == 4


def test_device_normalizer_table_valid_and_refusals() -> None:
    """Card Part 1 Item 1 & Item 4(3):
    The normaliser table:
    - `"cuda" -> "cuda:0"`, `"cuda:0" -> "cuda:0"`, `"cuda:2" -> "cuda:2"`, `"cpu" -> "cpu"`,
    - `"cuda:"`, `"cuda:-1"`, `"gpu"`, `"cuda:0 "`, `""` each refused with `BAKEOFF_JUDGE_DEVICE_INVALID`
      and a scrubbed message.
    """
    from reasoning_dataset_lab.pilot_b import bakeoff_judge as bj_mod
    from reasoning_dataset_lab.pilot_b import device as dev_mod

    valid_table = [
        ("cuda", "cuda:0"),
        ("cuda:0", "cuda:0"),
        ("cuda:2", "cuda:2"),
        ("cpu", "cpu"),
    ]
    for raw_dev, expected_dev in valid_table:
        assert dev_mod.normalize_judge_device(raw_dev) == expected_dev
        assert vm_judges.normalize_judge_device(raw_dev) == expected_dev
        assert bj_mod.normalize_judge_device(raw_dev) == expected_dev

    invalid_inputs: list[Any] = [
        "cuda:",
        "cuda:-1",
        "gpu",
        "cuda:0 ",
        " cuda:0",
        "cuda:0\n",
        "",
        "cuda:01",
        "CUDA:0",
        None,
        0,
        True,
    ]
    for bad_dev in invalid_inputs:
        with pytest.raises(dev_mod.DeviceRefusalError) as exc_dev:
            dev_mod.normalize_judge_device(bad_dev)
        assert exc_dev.value.code == "BAKEOFF_JUDGE_DEVICE_INVALID"
        assert exc_dev.value.failure_class == "BAKEOFF_JUDGE_DEVICE_INVALID"
        assert exc_dev.value.to_dict()["code"] == "BAKEOFF_JUDGE_DEVICE_INVALID"
        assert '"BAKEOFF_JUDGE_DEVICE_INVALID"' in exc_dev.value.to_json()

        with pytest.raises(vm_judges.RefusalError) as exc_vm:
            vm_judges.normalize_judge_device(bad_dev)
        assert exc_vm.value.failure_class == "BAKEOFF_JUDGE_DEVICE_INVALID"

        with pytest.raises(RdlabError) as exc_bj:
            bj_mod.TransformersJudgeTransport(
                receipts_dir=Path("/tmp/unused_receipts"),
                device=bad_dev,
            )
        assert exc_bj.value.code == "BAKEOFF_JUDGE_DEVICE_INVALID"
        assert isinstance(exc_bj.value.__cause__, dev_mod.DeviceRefusalError)

    # Verify token scrubbing on refusal message in both VM and package paths
    planted_tok = "hf_" + "SecretDeviceToken9876543210abcdef"
    with pytest.raises(vm_judges.RefusalError) as exc_vm_tok:
        vm_judges.normalize_judge_device(planted_tok)
    assert exc_vm_tok.value.failure_class == "BAKEOFF_JUDGE_DEVICE_INVALID"
    assert planted_tok not in str(exc_vm_tok.value)

    with pytest.raises(RdlabError) as exc_bj_tok:
        bj_mod.TransformersJudgeTransport(
            receipts_dir=Path("/tmp/unused_receipts"),
            device=planted_tok,
        )
    assert exc_bj_tok.value.code == "BAKEOFF_JUDGE_DEVICE_INVALID"
    assert isinstance(exc_bj_tok.value.__cause__, dev_mod.DeviceRefusalError)
    assert planted_tok not in str(exc_bj_tok.value)


def test_no_code_path_builds_child_argv_with_bare_cuda_across_all_modes(
    tmp_path: Path,
) -> None:
    """Card Part 1 Item 4(4):
    No code path in `vm_judges.py` or `bakeoff_judge.py` builds a child argv with `--device cuda`
    across `--stub`, `--until first_judge`, `--until first_load`, and `--time-one`.
    """
    from reasoning_dataset_lab.pilot_b import bakeoff_judge as bj_mod

    # 1. Run fake pipeline / launcher across `--stub`, `--until first_judge`, `--until first_load`, and `--time-one`
    #    and verify every recorded child argv in `judge_subprocesses.jsonl` never has `["--device", "cuda"]`
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "modes_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "modes_data", count=2)
    _attach_part_files(items_file, part_id="part-synthetic")

    work_t1 = tmp_path / "work_t1_direct"
    vm_judges._ensure_dryrun_venv_python_wrapper(work_t1 / "venv-judge" / "bin" / "python")
    vm_judges._ensure_dryrun_venv_python_wrapper(work_t1 / "venv-d3" / "bin" / "python")
    state_dir_direct = Path(os.environ["FAKE_COLAB_STATE_DIR"])
    subproc_direct = state_dir_direct / "judge_subprocesses.jsonl"
    if subproc_direct.exists():
        subproc_direct.unlink()
    vm_judges.run_judges_pipeline(
        mode="time-one",
        part_dir=items_file.parent,
        run_dir=tmp_path / "run_t1_direct",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        dryrun=False,
        repo_root=REPO_ROOT,
        work_dir=work_t1,
        progress_path=tmp_path / "run_t1_direct" / "progress.jsonl",
        only_judge_ids=("d3-mini",),
    )
    # the launcher runs below are stub/dryrun windows on these synthetic items: no part files beside them
    for part_file in ("part.json", "checksums.txt"):
        (items_file.parent / part_file).unlink()
    direct_rows = [
        json.loads(ln)
        for ln in subproc_direct.read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    assert len(direct_rows) == 1
    direct_argv = direct_rows[0]["argv"]
    direct_idx = direct_argv.index("--device")
    assert direct_argv[direct_idx + 1] != "cuda", (
        f"Bare '--device cuda' found in time-one: {direct_argv}"
    )
    assert direct_argv[direct_idx + 1] == "cuda:0"

    mode_runs = [
        ("dry", "--stub --dry", None),
        ("stub", "--stub", "cpu"),
        ("first_judge", "--stub --until first_judge", None),
        ("first_load", "--stub --until first_load", "cpu"),
        ("time_one", "--time-one", "cuda:0"),
        ("counted_default", "", "cpu"),
    ]
    for label, flags, expected_dev in mode_runs:
        env_m = fake_colab.setup_fake_colab_environment(tmp_path / f"env_{label}")
        out_m = tmp_path / f"out_{label}"
        exports_m = _base_launcher_exports(
            env_m,
            open_lock=tmp_path / f"lock_{label}.lock",
            receipts_dir=receipts_dir,
            hf_home=hf_home,
            items_file=items_file,
        )
        proc_m = subprocess.run(
            [
                "bash",
                "-c",
                f"{exports_m} bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' {flags} --out-dir '{_to_wsl_path(out_m)}' --run-id mode-{label}-01",
            ],
            stdin=subprocess.DEVNULL,
            capture_output=True,
            text=True,
            timeout=90,
            check=False,
        )
        assert proc_m.returncode == 0, f"label={label} stderr={proc_m.stderr}"
        subproc_file = env_m["state_dir"] / "judge_subprocesses.jsonl"
        child_argvs: list[list[str]] = []
        if subproc_file.exists():
            subprocs = [
                json.loads(ln)
                for ln in subproc_file.read_text(encoding="utf-8").splitlines()
                if ln.strip()
            ]
            child_argvs = [list(sp["argv"]) for sp in subprocs]
        else:
            subprocs = []
        if expected_dev is None:
            assert child_argvs == []
            if label == "dry":
                assert "colab usage" in proc_m.stdout
                assert "--env RDLAB_STEP=alive" in proc_m.stdout
            continue
        assert len(child_argvs) >= 1
        for sp, argv in zip(subprocs, child_argvs, strict=True):
            idx = argv.index("--device")
            assert argv[idx + 1] != "cuda", (
                f"Bare '--device cuda' found in {label}: {argv}"
            )
            assert argv[idx + 1] == expected_dev
            assert sp["device"] == expected_dev

    # 2. Check `resolve_judge_device` across all four mode/stage combinations
    assert (
        vm_judges.resolve_judge_device(
            mode="stub", dryrun=True, real_load_on_cpu=False
        )
        == "cpu"
    )
    assert (
        vm_judges.resolve_judge_device(
            mode="stub", dryrun=False, real_load_on_cpu=False
        )
        == "cpu"
    )
    assert (
        vm_judges.resolve_judge_device(
            mode="stub", dryrun=False, real_load_on_cpu=True
        )
        == "cpu"
    )
    assert (
        vm_judges.resolve_judge_device(
            mode="time-one", dryrun=False, real_load_on_cpu=False
        )
        == "cuda:0"
    )
    assert (
        vm_judges.resolve_judge_device(
            mode="time-one", dryrun=False, real_load_on_cpu=False, raw_device="cuda"
        )
        == "cuda:0"
    )

    # 3. Also verify `bakeoff_judge` normalises `--device cuda` to `"cuda:0"`
    assert bj_mod.normalize_judge_device("cuda") == "cuda:0"


def test_device_check_passes_for_cuda_0_and_refuses_for_cuda_in_stub_before_download(
    tmp_path: Path,
) -> None:
    """Card Part 1 Item 2 & Item 4(5):
    `device_check` passes for `"cuda:0"` in both venvs and refuses with `DEVICE_INDEX_CHECK_FAILED`
    before any download when `"cuda"` is injected, even in `--stub`.
    """
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "dev_chk_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "dev_chk_data", count=2)

    # 1. `--stub --until device_check` runs `device_check` in both `venv-judge` and `venv-d3` for `"cuda:0"` and passes
    env_ok = fake_colab.setup_fake_colab_environment(tmp_path / "env_dc_ok")
    out_ok = tmp_path / "out_dc_ok"
    exports_ok = _base_launcher_exports(
        env_ok,
        open_lock=tmp_path / "dc_ok.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_ok = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_ok} bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until device_check --out-dir '{_to_wsl_path(out_ok)}' --run-id dc-ok-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_ok.returncode == 0, f"stderr={proc_ok.stderr}"
    status_ok = json.loads((out_ok / "status.json").read_text(encoding="utf-8"))
    receipt_ok = json.loads((out_ok / "vm_receipt.json").read_text(encoding="utf-8"))
    vm_fs_ok = env_ok["state_dir"] / "vm_fs"
    gate_ok = json.loads((vm_fs_ok / "gate_status.json").read_text(encoding="utf-8"))
    assert status_ok["stopped_after"] == "device_check"
    assert receipt_ok["stopped_after"] == "device_check"
    for doc in (status_ok, receipt_ok, gate_ok):
        dc = doc["device_check"]
        assert dc["ok"] is True
        assert dc["device"] == "cuda:0"
        assert dc["venvs"]["venv-judge"]["ok"] is True
        assert dc["venvs"]["venv-judge"]["device"] == "cuda:0"
        assert dc["venvs"]["venv-judge"]["device_index"] == 0
        assert dc["venvs"]["venv-d3"]["ok"] is True
        assert dc["venvs"]["venv-d3"]["device"] == "cuda:0"
        assert dc["venvs"]["venv-d3"]["device_index"] == 0

    # 2. When `"cuda"` is injected into `device_check` in `--stub`, it refuses with `DEVICE_INDEX_CHECK_FAILED`
    #    before any download child starts
    env_fail = fake_colab.setup_fake_colab_environment(tmp_path / "env_dc_fail")
    out_fail = tmp_path / "out_dc_fail"
    exports_fail = _base_launcher_exports(
        env_fail,
        open_lock=tmp_path / "dc_fail.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_fail = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_fail} export FAKE_COLAB_DEVICE_CHECK_DEVICE=cuda; bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --out-dir '{_to_wsl_path(out_fail)}' --run-id dc-fail-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_fail.returncode == 2, f"stderr={proc_fail.stderr}"
    status_fail = json.loads((out_fail / "status.json").read_text(encoding="utf-8"))
    receipt_fail = json.loads((out_fail / "vm_receipt.json").read_text(encoding="utf-8"))
    outcome_fail = json.loads(
        (out_fail / "outcome.draft.json").read_text(encoding="utf-8")
    )
    assert status_fail["failure_class"] == "DEVICE_INDEX_CHECK_FAILED"
    assert receipt_fail["failure_class"] == "DEVICE_INDEX_CHECK_FAILED"
    assert status_fail["device_check"]["ok"] is False
    assert status_fail["device_check"]["device"] == "cuda"
    assert "Expected a torch.device with a specified index" in json.dumps(
        status_fail["device_check"]
    )
    assert "DEVICE_INDEX_CHECK_FAILED" in outcome_fail["why"]
    assert "liveness" not in outcome_fail["why"]

    lc_fail_path = env_fail["state_dir"] / "child_lifecycle.jsonl"
    if lc_fail_path.exists():
        lc_fail = [
            json.loads(ln)
            for ln in lc_fail_path.read_text(encoding="utf-8").splitlines()
            if ln.strip()
        ]
    else:
        lc_fail = []
    assert [e for e in lc_fail if e.get("event") == "download_child"] == []
    assert [e for e in lc_fail if e.get("event") == "judge_child"] == []


def test_only_judges_d3_mini_under_time_one_downloads_verifies_and_runs_only_d3_mini(
    tmp_path: Path,
) -> None:
    """Card Part 1 Item 3 & Item 4(6):
    `RDLAB_ONLY_JUDGES=d3-mini` under `--time-one` downloads, verifies, and runs only `d3-mini`,
    and `status.json`, `vm_receipt.json`, `time_one_summary.json`, `judge_done/`, and the outcome draft
    carry only `d3-mini` and `"only_judges": ["d3-mini"]`.
    """
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "only_d3_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "only_d3_data", count=2)
    env_only = fake_colab.setup_fake_colab_environment(tmp_path / "env_only_d3")
    out_only = tmp_path / "out_only_d3"
    exports_only = _base_launcher_exports(
        env_only,
        open_lock=tmp_path / "only_d3.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_only = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_only} RDLAB_ONLY_JUDGES=d3-mini bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --time-one --out-dir '{_to_wsl_path(out_only)}' --run-id only-d3-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=90,
        check=False,
    )
    assert proc_only.returncode == 0, f"stderr={proc_only.stderr}"

    lc_only = [
        json.loads(ln)
        for ln in (env_only["state_dir"] / "child_lifecycle.jsonl")
        .read_text(encoding="utf-8")
        .splitlines()
        if ln.strip()
    ]
    assert [e["judge_id"] for e in lc_only if e["event"] == "download_child"] == [
        "d3-mini"
    ]
    assert [e["judge_id"] for e in lc_only if e["event"] == "parent_verify"] == [
        "d3-mini"
    ]
    assert [e["judge_id"] for e in lc_only if e["event"] == "judge_child"] == [
        "d3-mini"
    ]

    status_doc = json.loads((out_only / "status.json").read_text(encoding="utf-8"))
    receipt_doc = json.loads((out_only / "vm_receipt.json").read_text(encoding="utf-8"))
    summary_doc = json.loads(
        (out_only / "time_one_summary.json").read_text(encoding="utf-8")
    )
    outcome_doc = json.loads(
        (out_only / "outcome.draft.json").read_text(encoding="utf-8")
    )

    assert status_doc["only_judges"] == ["d3-mini"]
    assert status_doc["judge_order"] == ["d3-mini"]
    assert receipt_doc["only_judges"] == ["d3-mini"]
    assert receipt_doc["judge_order"] == ["d3-mini"]
    assert list(receipt_doc["judges"].keys()) == ["d3-mini"]
    assert summary_doc["only_judges"] == ["d3-mini"]
    assert summary_doc["judge_order"] == ["d3-mini"]
    assert list(summary_doc["judges"].keys()) == ["d3-mini"]
    assert outcome_doc["only_judges"] == ["d3-mini"]
    assert outcome_doc["judges_completed"] == ["d3-mini"]

    done_files = sorted(p.name for p in (out_only / "judge_done").glob("*.json"))
    row_files = sorted(p.name for p in (out_only / "rows").glob("*.jsonl"))
    assert done_files == ["d3-mini.json"]
    assert row_files == ["d3-mini.jsonl"]


def test_only_judges_refused_with_stub_with_judge_order_unknown_id_and_duplicate(
    tmp_path: Path,
) -> None:
    """Card Part 1 Item 3 & Item 4(7):
    `RDLAB_ONLY_JUDGES` is refused (`ONLY_JUDGES_INVALID`, before `colab new`) with `--stub`,
    with `RDLAB_JUDGE_ORDER`, on an unknown id, and on a duplicate (plus empty or whitespace).
    """
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "only_ref_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "only_ref_data", count=2)
    env_ref = fake_colab.setup_fake_colab_environment(tmp_path / "env_only_ref")
    exports_ref = _base_launcher_exports(
        env_ref,
        open_lock=tmp_path / "only_ref.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )

    perm_all = (
        "flow-judge-v0.1,granite-guardian-4.1-8b,mu-judge,nemotron-3-nano-4b,d3-mini"
    )
    refusal_cases = [
        # (env_prefix, cli_flags)
        ("RDLAB_ONLY_JUDGES='d3-mini'", "--stub"),
        ("RDLAB_ONLY_JUDGES='d3-mini'", "--stub --until first_load"),
        (
            f"RDLAB_ONLY_JUDGES='d3-mini' RDLAB_JUDGE_ORDER='{perm_all}'",
            "--time-one",
        ),
        ("RDLAB_ONLY_JUDGES='unknown-judge'", "--time-one"),
        ("RDLAB_ONLY_JUDGES='d3-mini,d3-mini'", "--time-one"),
        ("RDLAB_ONLY_JUDGES=''", "--time-one"),
        ("RDLAB_ONLY_JUDGES='d3-mini,'", "--time-one"),
        ("RDLAB_ONLY_JUDGES=' d3-mini'", "--time-one"),
    ]

    for idx, (env_prefix, cli_flags) in enumerate(refusal_cases):
        proc = subprocess.run(
            [
                "bash",
                "-c",
                f"{exports_ref} {env_prefix} bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' {cli_flags} --out-dir '{_to_wsl_path(tmp_path / f'out_only_ref_{idx}')}' --run-id only-ref-{idx:02d}",
            ],
            stdin=subprocess.DEVNULL,
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        assert proc.returncode == 2, (
            f"case={idx} ({env_prefix} {cli_flags}) rc={proc.returncode} stderr={proc.stderr}"
        )
        assert "ONLY_JUDGES_INVALID" in proc.stderr
        assert not env_ref["calls_log"].exists(), (
            f"Fake colab was called for refusal case {idx}: {env_prefix} {cli_flags}"
        )
        assert not env_ref["sentinel_called"].exists()


def test_part2_item1_forward_child_timeout_env_vars_into_colab_exec(
    tmp_path: Path,
) -> None:
    """Card Part 2 Item 1:
    Setting `RDLAB_FIRST_LOAD_TIMEOUT_SECONDS=900` (and the other child-timeout/heartbeat vars)
    on the rig forwards `--env RDLAB_FIRST_LOAD_TIMEOUT_SECONDS=900` into `colab exec` argv
    recorded by `fake_colab` and is read by `vm_judges.py`.
    """
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "p2_item1_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "p2_item1_data", count=2)
    env_p = fake_colab.setup_fake_colab_environment(tmp_path / "env_p2_item1")
    out_p = tmp_path / "out_p2_item1"
    exports_p = _base_launcher_exports(
        env_p,
        open_lock=tmp_path / "p2_item1.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    extra_env = (
        "export RDLAB_FIRST_LOAD_TIMEOUT_SECONDS=900; "
        "export RDLAB_JUDGE_CHILD_TIMEOUT_SECONDS=750; "
        "export RDLAB_GPU_GATE_TIMEOUT_SECONDS=45; "
        "export RDLAB_DOWNLOAD_CHILD_TIMEOUT_SECONDS=480; "
        "export RDLAB_CHILD_WALL_MARGIN_SECONDS=40; "
        "export RDLAB_JUDGE_CHILD_HEARTBEAT_SECONDS=15; "
    )
    proc = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_p} {extra_env} bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until first_load --out-dir '{_to_wsl_path(out_p)}' --run-id p2-item1-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=90,
        check=False,
    )
    assert proc.returncode == 0, f"stderr={proc.stderr}"
    calls = [
        json.loads(ln)
        for ln in env_p["calls_log"].read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    run_exec_calls = [
        c
        for c in calls
        if c["subcmd"] == "exec" and "RDLAB_STEP=run" in c["args"]
    ]
    assert len(run_exec_calls) == 1
    run_args = run_exec_calls[0]["args"]
    for expected_kv in (
        "RDLAB_FIRST_LOAD_TIMEOUT_SECONDS=900",
        "RDLAB_JUDGE_CHILD_TIMEOUT_SECONDS=750",
        "RDLAB_GPU_GATE_TIMEOUT_SECONDS=45",
        "RDLAB_DOWNLOAD_CHILD_TIMEOUT_SECONDS=480",
        "RDLAB_CHILD_WALL_MARGIN_SECONDS=40",
        "RDLAB_JUDGE_CHILD_HEARTBEAT_SECONDS=15",
    ):
        assert expected_kv in run_args, f"Missing {expected_kv} in {run_args}"

    j_subprocs = [
        json.loads(ln)
        for ln in (env_p["state_dir"] / "judge_subprocesses.jsonl")
        .read_text(encoding="utf-8")
        .splitlines()
        if ln.strip()
    ]
    assert len(j_subprocs) == 1
    assert j_subprocs[0]["timeout_seconds"] == 900.0


def test_part2_item2_fail_closed_vram_probe(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Card Part 2 Item 2:
    On `cuda:0` (or any `cuda:<idx>`), if `nvidia-smi` exits non-zero, returns empty stdout,
    returns non-integer output, or is missing, `query_gpu_vram_peak_mib` and the judge pass
    fail closed with `BAKEOFF_JUDGE_VRAM_PROBE_FAILED` instead of silently returning `0`.
    """
    from reasoning_dataset_lab.errors import RdlabError
    from reasoning_dataset_lab.pilot_b import bakeoff_judge as bj_mod

    planted_tok = "hf_" + "VramProbeSecretToken998877665544"

    # 1. Direct `query_gpu_vram_peak_mib` fail-closed checks
    for bad_proc in (
        subprocess.CompletedProcess(
            args=[], returncode=9, stdout="", stderr=f"driver fail {planted_tok}"
        ),
        subprocess.CompletedProcess(args=[], returncode=0, stdout="\n  \n", stderr=""),
        subprocess.CompletedProcess(
            args=[], returncode=0, stdout=f"N/A {planted_tok}\n", stderr=""
        ),
    ):
        monkeypatch.setattr(subprocess, "run", lambda *a, _p=bad_proc, **kw: _p)
        with pytest.raises(RdlabError) as exc_v:
            bj_mod.query_gpu_vram_peak_mib()
        assert exc_v.value.code == "BAKEOFF_JUDGE_VRAM_PROBE_FAILED"
        assert planted_tok not in str(exc_v.value)

    def _raise_missing(*_a: object, **_kw: object) -> object:
        raise FileNotFoundError(2, f"No such file or directory {planted_tok}", "nvidia-smi")

    monkeypatch.setattr(subprocess, "run", _raise_missing)
    with pytest.raises(RdlabError) as exc_m:
        bj_mod.query_gpu_vram_peak_mib()
    assert exc_m.value.code == "BAKEOFF_JUDGE_VRAM_PROBE_FAILED"
    assert planted_tok not in str(exc_m.value)

    # 2. `run_bakeoff_judge` on `cuda:0` fails closed when `query_gpu_vram_peak_mib` fails
    items_file = _make_synthetic_public_items(tmp_path / "vram_items", count=2)
    with pytest.raises(RdlabError) as exc_run:
        bj_mod.run_bakeoff_judge(
            part_dir=items_file,
            output_dir=tmp_path / "vram_out",
            judge="nemotron-3-nano-4b",
            limit_items=1,
            transport=bj_mod.DeterministicFakeJudgeTransport(),
            device="cuda:0",
            torch_dtype="bfloat16",
            run_canary=False,
            vram_probe=bj_mod.query_gpu_vram_peak_mib,
        )
    assert exc_run.value.code == "BAKEOFF_JUDGE_VRAM_PROBE_FAILED"


def test_part2_item3_live_rate_from_colab_usage_and_cost_cap_fetch_before_stop(
    tmp_path: Path,
) -> None:
    """Card Part 2 Item 3:
    With a fake clock and fake `colab usage` returning `13.08/hr`, a `--cap 2.5` run fetches
    `/content/result.tar.gz` and `/content/status.json` and stops at `runtime * 13.08 / 3600 >= 2.5`
    (`<= 689` s) with `status.json` recording the live rate and `result.tar.gz` fetched before `colab stop`.
    """
    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "p2_item3_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "p2_item3_data", count=2)
    env_c = fake_colab.setup_fake_colab_environment(tmp_path / "env_p2_item3")
    out_c = tmp_path / "out_p2_item3"
    clock_file = tmp_path / "fake_clock.txt"
    clock_file.write_text("1000000\n", encoding="utf-8", newline="\n")

    exports_c = _base_launcher_exports(
        env_c,
        open_lock=tmp_path / "p2_item3.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    extra_c = (
        f"export RDLAB_FAKE_CLOCK_FILE='{_to_wsl_path(clock_file)}'; "
        "export RDLAB_FAKE_CLOCK_STEP_SECONDS=689; "
        "export FAKE_COLAB_USAGE_RATE='13.08'; "
        "export FAKE_COLAB_EXEC_SLEEP='15'; "
        "export FAKE_COLAB_WRITE_RESULT_TAR_BEFORE_SLEEP=1; "
        "export RDLAB_COST_CAP_POLL_SECONDS=1; "
    )
    # Advance the fake clock file by 689s on the first armed poll inside COST_CAP_PID
    clock_file.write_text("1000000\n", encoding="utf-8", newline="\n")
    proc = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_c} {extra_c} bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --time-one --cap 2.5 --out-dir '{_to_wsl_path(out_c)}' --run-id p2-cap-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc.returncode == 2, f"stdout={proc.stdout}\nstderr={proc.stderr}"
    assert (out_c / "result.tar.gz").is_file()
    assert (out_c / "status.json").is_file()

    status_doc = json.loads((out_c / "status.json").read_text(encoding="utf-8"))
    outcome_doc = json.loads((out_c / "outcome.draft.json").read_text(encoding="utf-8"))
    assert status_doc["live_rate"] == 13.08
    assert status_doc["live_usage_rate_per_hour"] == 13.08
    assert isinstance(status_doc["rate_read_at"], str) and status_doc["rate_read_at"]
    assert status_doc["cost_cap_reached"] is True
    assert status_doc["runtime_seconds"] <= 689
    assert (status_doc["runtime_seconds"] * 13.08 / 3600.0) >= 2.5

    assert outcome_doc["rate_per_hour"] == 13.08
    assert outcome_doc["live_rate"] == 13.08
    assert outcome_doc["runtime_seconds"] <= 689
    assert outcome_doc["outcome"] == "stopped_cost_cap"

    calls = [
        json.loads(ln)
        for ln in env_c["calls_log"].read_text(encoding="utf-8").splitlines()
        if ln.strip()
    ]
    subcmds_and_args = [(c["subcmd"], c["args"]) for c in calls]
    usage_idx = next(i for i, (s, _) in enumerate(subcmds_and_args) if s == "usage")
    dl_tar_idx = next(
        i
        for i, (s, a) in enumerate(subcmds_and_args)
        if s == "download" and "/content/result.tar.gz" in a
    )
    dl_status_idx = next(
        i
        for i, (s, a) in enumerate(subcmds_and_args)
        if s == "download" and "/content/status.json" in a
    )
    stop_idx = next(i for i, (s, _) in enumerate(subcmds_and_args) if s == "stop")
    assert usage_idx < dl_tar_idx < stop_idx
    assert usage_idx < dl_status_idx < stop_idx


def test_part2_item4_cli_alive_probe_and_distinct_failure_class(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
) -> None:
    """Card Part 2 Item 4:
    - `vm_judges.py --step alive` prints `VM_ALIVE_OK` and returns `0`.
    - `launch_judges.sh` recovers when the first `alive` probe fails with `Connection was lost`
      and the second try succeeds.
    - `launch_judges.sh` reports `CLI_KERNEL_CONNECTION_LOST_BEFORE_GATE` when all 3 alive probe
      tries fail, and `VM_GATE_REFUSED` when the gate script actually runs and refuses.
    """
    # 1. Direct `--step alive`
    rc_alive = vm_judges.main(["--step", "alive"])
    assert rc_alive == 0
    captured = capsys.readouterr()
    assert "VM_ALIVE_OK" in captured.out

    receipts_dir, hf_home = _make_synthetic_judge_snapshots_and_receipts(
        tmp_path / "p2_item4_data"
    )
    items_file = _make_synthetic_public_items(tmp_path / "p2_item4_data", count=2)

    # 2. First alive probe loses connection, second succeeds -> full run succeeds
    env_rec = fake_colab.setup_fake_colab_environment(tmp_path / "env_alive_recover")
    out_rec = tmp_path / "out_alive_recover"
    exports_rec = _base_launcher_exports(
        env_rec,
        open_lock=tmp_path / "alive_rec.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_rec = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_rec} export FAKE_COLAB_ALIVE_FAIL_COUNT=1; export RDLAB_ALIVE_PROBE_SLEEP_SECONDS=0; "
            f"bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_rec)}' --run-id alive-rec-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_rec.returncode == 0, f"stderr={proc_rec.stderr}"
    alive_attempts_rec = [
        json.loads(ln)
        for ln in (env_rec["state_dir"] / "alive_attempts.jsonl")
        .read_text(encoding="utf-8")
        .splitlines()
        if ln.strip()
    ]
    assert len(alive_attempts_rec) == 2
    assert alive_attempts_rec[0]["failed"] is True
    assert alive_attempts_rec[1]["failed"] is False

    # 3. All 3 alive probe tries lose connection -> CLI_KERNEL_CONNECTION_LOST_BEFORE_GATE
    env_lost = fake_colab.setup_fake_colab_environment(tmp_path / "env_alive_lost")
    out_lost = tmp_path / "out_alive_lost"
    exports_lost = _base_launcher_exports(
        env_lost,
        open_lock=tmp_path / "alive_lost.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_lost = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_lost} export FAKE_COLAB_ALIVE_FAIL_COUNT=3; export RDLAB_ALIVE_PROBE_SLEEP_SECONDS=0; "
            f"bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_lost)}' --run-id alive-lost-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_lost.returncode == 2
    assert "CLI_KERNEL_CONNECTION_LOST_BEFORE_GATE" in proc_lost.stderr
    outcome_lost = json.loads(
        (out_lost / "outcome.draft.json").read_text(encoding="utf-8")
    )
    assert outcome_lost["failure_class"] == "CLI_KERNEL_CONNECTION_LOST_BEFORE_GATE"
    assert "CLI_KERNEL_CONNECTION_LOST_BEFORE_GATE" in outcome_lost["why"]
    assert "VM liveness gate failed" not in outcome_lost["why"]

    # 4. Gate script runs and refuses -> VM_GATE_REFUSED
    env_gref = fake_colab.setup_fake_colab_environment(tmp_path / "env_gate_refused")
    out_gref = tmp_path / "out_gate_refused"
    exports_gref = _base_launcher_exports(
        env_gref,
        open_lock=tmp_path / "gate_ref.lock",
        receipts_dir=receipts_dir,
        hf_home=hf_home,
        items_file=items_file,
    )
    proc_gref = subprocess.run(
        [
            "bash",
            "-c",
            f"{exports_gref} export FAKE_COLAB_DISK_FREE_BYTES=1000000; "
            f"bash '{_to_wsl_path(LAUNCH_JUDGES_SH)}' --stub --until venv_sync --out-dir '{_to_wsl_path(out_gref)}' --run-id gate-ref-01",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    assert proc_gref.returncode == 2
    outcome_gref = json.loads(
        (out_gref / "outcome.draft.json").read_text(encoding="utf-8")
    )
    assert outcome_gref["failure_class"] == "VM_GATE_REFUSED"


def test_part2_item5_uv_wheel_sha_hook_behind_explicit_test_seam(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Card Part 2 Item 5:
    `install_pinned_uv_wheel` in `scripts/colab/vm_judges.py` does not read `FAKE_COLAB_STATE_DIR`
    or `uv_state.json`; with the production `resolve_expected_uv_wheel_sha256` unpatched, setting
    `FAKE_COLAB_STATE_DIR` has zero effect on the expected SHA-256 check.
    """
    _pin = _use_per_test_pinned_uv_dir(tmp_path, monkeypatch)
    import inspect

    src = inspect.getsource(vm_judges.install_pinned_uv_wheel)
    assert "FAKE_COLAB_STATE_DIR" not in src
    assert "uv_state.json" not in src

    # Restore real production `resolve_expected_uv_wheel_sha256` (undoing the test fixture monkeypatch)
    assert hasattr(vm_judges.resolve_expected_uv_wheel_sha256, "__wrapped__"), (
        "Expected test fixture wrapper to expose production function on __wrapped__"
    )
    real_resolve = getattr(vm_judges.resolve_expected_uv_wheel_sha256, "__wrapped__")
    real_src = inspect.getsource(real_resolve)
    assert "def resolve_expected_uv_wheel_sha256(" in real_src
    assert "FAKE_COLAB_STATE_DIR" not in real_src
    assert "uv_state.json" not in real_src
    monkeypatch.setattr(vm_judges, "resolve_expected_uv_wheel_sha256", real_resolve)

    fake_state = tmp_path / "prod_seam_state"
    fake_state.mkdir(parents=True, exist_ok=True)
    (fake_state / "uv_state.json").write_text(
        json.dumps({"expected_uv_wheel_sha256": "a" * 64}) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    monkeypatch.setenv("FAKE_COLAB_STATE_DIR", str(fake_state))
    assert vm_judges.resolve_expected_uv_wheel_sha256() == vm_judges.PINNED_UV_WHEEL_SHA256
    assert vm_judges.resolve_expected_uv_wheel_sha256("  " + ("B" * 64) + "  ") == "b" * 64


